import{z as i,x as d,o as E,c,q as t,j as r,D as e,d as s,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"穷尽性检查","description":"","frontmatter":{"title":"穷尽性检查","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exhaustiveness-check.md","filePath":"cs/exhaustiveness-check.md","lastUpdated":1791063341000}'),l={name:"cs/exhaustiveness-check.md"};function B(p,a,h,D,_,m){const o=d("Mermaid");return E(),c("div",null,[a[2]||(a[2]=t('<h1 id="穷尽性检查" tabindex="-1">穷尽性检查 <a class="header-anchor" href="#穷尽性检查" aria-label="Permalink to &quot;穷尽性检查&quot;">​</a></h1><div class="epigraph"><p>若存在一个值，使得所有子句都失败，则匹配不穷尽。无用子句是永远被前面挡住的模式。二者都可在构造子有限时判定。</p><footer>—— 据 Maranget, Warnings for Pattern Matching, 2007；Peyton Jones 等 GHC 诊断；Pierce 对 case 穷尽的讨论整理</footer></div><p>上一课<a href="/cs/adt-pattern-compile">模式匹配编译</a>把子句变成判定树。缺口是<strong>静态诊断</strong>：没写 <code>Nothing</code>、或 <code>x::_</code> 挡住了后面的 <code>[]</code>。Maranget 用「反例值」与矩阵的有用性。本课钉检查，不重写分派代码生成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译判定树时，默认边若到达「无子句」则运行时失败（ML 的 <code>Match</code> 异常）。语言可拒绝不穷尽，或警告。算法：在子句矩阵上求是否存在向量 \\(v\\) 逃过所有行；若存在，pretty-print 成模式当反例。无用行：去掉该行后覆盖不变。缺口是<strong>覆盖关系</strong>，不是词法。</p><p>与<a href="/cs/subtyping-variance">子类型</a>：开世界（可另编译新子类）不能穷尽；ADT 闭世界可以。OOP 的 visitor 穷尽靠密封类或默认方法。<span class="marginnote">术语翻译：穷尽性检查就是用「找一个能绕过所有分支的值」的手段来做「判断 match 是否漏了分支」的事——找不到这样的值，才算穷尽。所以它的输出往往是反例，而不只是「通过/不通过」。</span></p><h3 id="警告不是健全性定理" tabindex="-1">警告不是健全性定理 <a class="header-anchor" href="#警告不是健全性定理" aria-label="Permalink to &quot;警告不是健全性定理&quot;">​</a></h3><p>忽略警告仍可生成代码。依值类型里「穷尽」更强，后课点名。此处是代数数据类型上的模式覆盖。</p><p><span class="marginnote">Maranget 2007（JFP）。GHC <code>-Wincomplete-patterns</code>。本课不把 SMT 当穷尽引擎，尽管守卫里的布尔可用求解器辅助。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>空类型、空构造子、通配。递归：按列展开构造子，对每个构造子形成子矩阵。反例：沿失败边收集构造子前缀。守卫：保守当「可能失败」，故带守卫的子句不贡献穷尽——除非语言另有分析。</p>',11)),(E(),r(n,null,{default:e(()=>[A(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%AD%90%E5%8F%A5%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20U%5B%22%E6%9C%89%E7%94%A8%E6%80%A7%22%5D%0A%20%20U%20--%3E%20EX%5B%22%E5%8F%8D%E4%BE%8B%E5%80%BC%E6%88%96%E7%A9%B7%E5%B0%BD%22%5D%0A%20%20U%20--%3E%20RED%5B%22%E6%97%A0%E7%94%A8%E5%AD%90%E5%8F%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与错误恢复：不穷尽是类型/模式层诊断，不是语法 <code>error</code> 记号。<span class="marginnote">数字实例：对 <code>type t = A | B</code>，若两个构造子的分支都没写，编译器会把 <code>A</code>、<code>B</code> 两个反例都列出来；只漏 <code>A</code> 时就只报 <code>A</code>。反例精确指出该补哪一枝，而不是笼统甩一句「不穷尽」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数：构造子笛卡尔积。实用：按列剪枝、共享。记录模式、或模式（or-pattern）是覆盖的糖。可变与并发不在覆盖里：值在匹配中途被改是内存模型，后课。</p>',3)),(E(),r(n,null,{default:e(()=>[A(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%EF%BC%9A%E5%AD%90%E5%8F%A5%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20B%7B%22%E9%A6%96%E5%88%97%E6%98%AF%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E9%80%9A%E9%85%8D%E7%AC%A6%22%7C%20C%5B%22%E5%88%A0%E5%8E%BB%E8%AF%A5%E5%88%97%E4%B8%8E%E5%AF%B9%E5%BA%94%E8%A1%8C%22%5D%20--%3E%20R%5B%22%E9%80%92%E5%BD%92%E5%88%A4%E5%AE%9A%E5%89%A9%E4%BD%99%E7%9F%A9%E9%98%B5%22%5D%0A%20%20B%20--%3E%7C%22%E6%9E%84%E9%80%A0%E5%AD%90%22%7C%20D%5B%22%E6%8C%89%E8%AF%A5%E7%B1%BB%E5%9E%8B%E6%AF%8F%E4%B8%AA%E6%9E%84%E9%80%A0%E5%AD%90%E5%B1%95%E5%BC%80%E6%88%90%E5%AD%90%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20E%5B%22%E5%90%84%E5%AD%90%E7%9F%A9%E9%98%B5%E5%88%86%E5%88%AB%E9%80%92%E5%BD%92%22%5D%0A%20%20R%20--%3E%20F%7B%22%E9%80%83%E9%80%B8%E8%B7%AF%E5%BE%84%E5%85%A8%E8%A2%AB%E5%A0%B5%E6%AD%BB%EF%BC%9F%22%7D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20G%5B%22%E5%88%A4%E5%AE%9A%E7%A9%B7%E5%B0%BD%22%5D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20H%5B%22%E8%BE%93%E5%87%BA%E5%8F%8D%E4%BE%8B%EF%BC%9A%E6%8B%BC%E6%8E%A5%E6%9E%84%E9%80%A0%E5%AD%90%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">直觉类比：可以把它想象成安检演练——每一行模式是一扇门，编译器扮演「千方百计想溜进去的入侵者」；只要还存在一条没人拦的路，演练就报警，并把那条路线画给你看，这条路线就是反例值。</span></p><p>不要用「加一个 <code>_</code>」当唯一建议而不展示反例；反例才教人补哪一枝。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GADT 细化后的不可达模式全文。后课默认：闭 ADT 可查穷尽与无用。下一课依值类型：穷尽可依赖值，检查变成证明。</p><p>也不把 Prolog 的子句搜索当穷尽性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>穷尽 = 不存在逃逸值；无用 = 覆盖不变。</li><li>闭的构造子世界可判定；开世界不能。</li><li>守卫使检查保守。</li><li>出处：Maranget, 2007；对照 Augustsson；Pierce TAPL case。</li></ul>',7))])}const F=i(l,[["render",B]]);export{C as __pageData,F as default};
